    ALTER COLUMN default_slot_length_in_minutes SET NOT NULL;

ALTER TABLE calendar
    ADD CONSTRAINT calendar_range_ck
    CHECK (
        default_slot_length_in_minutes >= 5
        AND default_slot_length_in_minutes <= 240
    );

-- Application inserts and direct database writes share this constraint.
COMMIT;

